package ru.truetv.launcher;
import android.app.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.*;
import android.os.*;
import android.preference.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;

/** Native tests of radio/focus independence, action hints/order and all appearance modes. */
public class AppearanceCheck extends Instrumentation {
 private int total;private final StringBuilder report=new StringBuilder();
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private void check(boolean ok,String title){total++;report.append(ok?"PASS ":"FAIL ").append(title).append('\n');if(!ok)throw new AssertionError(title);}
 private void main(Runnable r){Throwable[] error=new Throwable[1];runOnMainSync(()->{try{r.run();}catch(Throwable t){error[0]=t;}});waitForIdleSync();if(error[0]!=null)throw new AssertionError(error[0]);}
 private int background(Activity a){return ((ColorDrawable)a.findViewById(android.R.id.content).getBackground()).getColor();}
 private void shot(String name)throws Exception{Bitmap image=getUiAutomation().takeScreenshot();if(image==null)throw new AssertionError("screenshot");File folder=new File(getTargetContext().getExternalFilesDir(null),"appearance");folder.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(folder,name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
 public void onStart(){Bundle result=new Bundle();SettingsStore store=new SettingsStore(getTargetContext());try{
  store.data.edit().remove("theme").putBoolean("wallpaper",false).putBoolean("bt_asked",true).remove("menu_order").putBoolean("extended_menu_first",false).apply();
  SettingsActivity settings=(SettingsActivity)startActivitySync(new Intent(getTargetContext(),SettingsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
  main(()->{check(Ui.theme(settings).equals("black"),"owner black default independent of system theme");check(background(settings)==0xff000000,"settings uses black canvas");check(settings.findPreference("theme") instanceof SheetListPreference,"three-way theme selector");check(((ListPreference)settings.findPreference("theme")).getEntryValues().length==3,"exactly Dark Light Black options");check(settings.findPreference("wallpaper") instanceof CheckBoxPreference,"separate wallpaper checkbox");check(settings.findPreference("open_restart_first")==null,"old ambiguous toggle absent");check(settings.findPreference("menu_order")==null,"arbitrary menu order editor removed");check(settings.findPreference("extended_menu_first") instanceof ExtendedMenuPreference,"one extended-menu checkbox with glyphs");check(settings.findPreference("system_apps")!=null,"expert system apps entry at bottom");});
  final int[] picked={-1};final ChoiceDialog[] choice=new ChoiceDialog[1];main(()->choice[0]=ChoiceDialog.show(settings,"Icon size",new String[]{"32","64","96"},1,index->picked[0]=index));
  main(()->{check(choice[0].list.getCheckedItemPosition()==1,"exactly current value checked");check(choice[0].list.getSelectedItemPosition()==1,"cursor begins at current value");CheckedTextView row=(CheckedTextView)choice[0].list.getChildAt(0);check(!row.getText().toString().contains("✓"),"no checkmark in option text");check(row.getCompoundDrawables()[0]==null,"no decorative slider icon in option");});shot("dark-values");
  sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_UP);waitForIdleSync();main(()->{check(choice[0].list.getSelectedItemPosition()==0,"cursor moves independently");check(choice[0].list.getCheckedItemPosition()==1,"checked value stays until confirmation");});sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_UP);waitForIdleSync();main(()->check(choice[0].cancel.hasFocus(),"first option wraps to Cancel"));sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_DOWN);waitForIdleSync();main(()->check(choice[0].list.getSelectedItemPosition()==0&&choice[0].list.hasFocus(),"Cancel wraps to first option"));main(()->choice[0].list.performItemClick(choice[0].list.getChildAt(2),2,2));check(picked[0]==2,"one choice callback");
  final ActionSheet[] actions=new ActionSheet[1];main(()->{actions[0]=ActionSheet.show(settings,"App actions",new ActionSheet.Item("Restart app","restart",()->{},()->false),new ActionSheet.Item("App info","info",()->{}));ViewGroup text=(ViewGroup)((ViewGroup)actions[0].rows.get(0)).getChildAt(1);check(text.getChildCount()==2,"unavailable action has title and own subtitle");check(((TextView)text.getChildAt(1)).getText().toString().contains("Accessibility"),"permission explanation directly under action");check(text.getChildAt(1).getVisibility()==View.VISIBLE,"unavailable note visible");ViewGroup normal=(ViewGroup)((ViewGroup)actions[0].rows.get(1)).getChildAt(1);check(normal.getChildAt(1).getVisibility()==View.GONE,"available action has no permission note");check(actions[0].rows.get(0).isFocusable(),"grey action remains focusable");});shot("dark-actions");main(()->{check(actions[0].rows.get(1).getHeight()<=Ui.dp(settings,40),"compact normal rows at most40dp");actions[0].dialog.dismiss();
   ActionSheet.Item[] items={new ActionSheet.Item("Remove","remove",()->{}),new ActionSheet.Item("Close","close",()->{}),new ActionSheet.Item("Restart","restart",()->{}),new ActionSheet.Item("Info","info",()->{})};ActionSheet.Item[] ordered=AppMenus.ordered(settings,null,items);for(ActionSheet.Item item:ordered)check(!item.icon.equals("apps"),"no Open action");store.data.edit().putBoolean("extended_menu_first",true).apply();ActionSheet.Item[] changed=AppMenus.ordered(settings,null,items);check(changed[0].icon.equals("close")&&changed[1].icon.equals("restart"),"Close and Restart move to the top");check(changed.length==ordered.length,"position checkbox does not hide actions");store.data.edit().putBoolean("extended_menu_first",false).apply();check(AppMenus.ordered(settings,null,items)[0].icon.equals("remove"),"off restores original positions");check(changed[changed.length-1].icon.equals("info"),"App info remains last");settings.finish();});
  for(String theme:new String[]{"light","black"}){store.data.edit().putString("theme",theme).putBoolean("wallpaper",false).apply();SettingsActivity prefs=(SettingsActivity)startActivitySync(new Intent(getTargetContext(),SettingsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));main(()->{check(background(prefs)==Ui.background(prefs),theme+" settings background");check(Ui.light(prefs)==theme.equals("light"),theme+" foreground palette");prefs.finish();});CatalogActivity catalog=(CatalogActivity)startActivitySync(new Intent(getTargetContext(),CatalogActivity.class).putExtra("slot",-1).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));main(()->{View root=((ViewGroup)catalog.findViewById(android.R.id.content)).getChildAt(0);check(((ColorDrawable)root.getBackground()).getColor()==Ui.background(catalog),theme+" catalog background");EditText search=(EditText)((ViewGroup)root).getChildAt(0);check(search.getCurrentTextColor()==Ui.ink(catalog),theme+" readable catalog text");});shot(theme+"-catalog");main(catalog::finish);}
  store.data.edit().putString("theme","black").putBoolean("wallpaper",true).apply();SettingsActivity wallpaper=(SettingsActivity)startActivitySync(new Intent(getTargetContext(),SettingsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));main(()->{check((wallpaper.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_SHOW_WALLPAPER)!=0,"wallpaper enabled in settings");check(Color.alpha(background(wallpaper))<255,"wallpaper is not hidden behind opaque background");wallpaper.finish();});
  result.putString("report",report+"Checks="+total);finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("report",report+"ERROR "+e);finish(Activity.RESULT_CANCELED,result);}finally{store.data.edit().putString("theme","dark").putBoolean("wallpaper",false).remove("menu_order").putBoolean("extended_menu_first",false).apply();}}
}
